// Access to the PKI generated by scripts/pki/ensure-test-pki.sh into <repo>/.pki (git-ignored).
import { readFileSync } from 'node:fs';
import { base64Decode, base64Encode } from '@identra/sdk-core';

export const REPO = new URL('../../../../', import.meta.url);
const PKI = new URL('.pki/', REPO);

/** Every test of the test PKI validates at this instant unless it says otherwise. */
export const NOW = new Date('2026-06-01T00:00:00Z');

export function pemFile(path: string): string {
  return readFileSync(new URL(path, PKI), 'utf8');
}

/** DER of every certificate in a PEM file, in order. */
export function pemCerts(pem: string): Uint8Array[] {
  const blocks = [...pem.matchAll(/-----BEGIN CERTIFICATE-----([\s\S]+?)-----END CERTIFICATE-----/g)];
  return blocks.map((m) => base64Decode(m[1]!.replace(/\s+/g, '')));
}

const certAt = (path: string): Uint8Array => pemCerts(pemFile(path))[0]!;

/** Test PKI leaf certificate, e.g. leaf('vc'). */
export const leaf = (name: string): Uint8Array => certAt(`test/leaf/${name}.cert.pem`);
/** Test PKI CA certificate, e.g. ca('issuing'). */
export const ca = (name: string): Uint8Array => certAt(`test/ca/${name}/ca.cert.pem`);
export const b64 = (der: Uint8Array): string => base64Encode(der);
/** x5c of a test leaf and the CA that issued it. */
export const x5c = (leafName: string, caName = 'issuing'): string[] => [b64(leaf(leafName)), b64(ca(caName))];
